import {NewTaskChatInput} from '@github-ui/agent-sessions/components/new-task-chat-input/NewTaskChatInput'
import type {DropdownRepository} from '@github-ui/agent-sessions/hooks/useCopilotRepoFetching'
import type {IntentDetectionMode} from '@github-ui/agent-sessions/types/intent-detection-mode'
import type {SelectedAgent} from '@github-ui/agent-sessions/types/session'
import {isFeatureEnabled} from '@github-ui/feature-flags'

import styles from './TasksInChatInput.module.css'

type TasksInChatInputProps = {
  handleIntentDetectionSubmit: (
    content: string,
    selectedRepo: DropdownRepository | null,
    selectedBranch: string,
    selectedAgent: SelectedAgent,
    selectedMode?: IntentDetectionMode,
    modelId?: string,
    createPullRequest?: boolean,
  ) => Promise<void>
}
export function TasksInChatInput({handleIntentDetectionSubmit}: TasksInChatInputProps) {
  const decoupledModeEnabled = isFeatureEnabled('copilot_mission_control_decoupled_mode')

  return (
    <>
      <div className={styles.intentDetectionContainer}>
        <NewTaskChatInput
          eventType="chat_page"
          handleUserSubmit={handleIntentDetectionSubmit}
          submitWithModifier={false}
          decoupledModeEnabled={decoupledModeEnabled}
        />
      </div>
    </>
  )
}
